# Where the Anima model files are. Shared by every examples\anima\train_anima*.ps1 launcher (dot-sourced).
# Do not edit this file (it is tracked, so update.bat / git pull would conflict). Instead either:
#   - set it for one PowerShell window:
#       $env:ANIMA_MODEL_ROOT = "C:\path\to\forge\models"     (any folder with the Forge-style subfolders below)
#       $env:ANIMA38_QWEN35_TOKENIZER_DIR = "C:\path\to\qwen35_tokenizer"
#   - or create examples\anima\models.local.ps1 (git-ignored). It is read last, so any variable it sets wins, e.g.
#       $AnimaModelRoot = "C:\path\to\forge\models"
#       $Anima38File = "Anima-3.8B-v2.safetensors"
#       $AnimaDitDir = "C:\path\to\ComfyUI\models\diffusion_models"
#
# Default: <repo>\models with the same subfolders Forge uses, so you can point the root at a Forge "models" folder:
#   <root>\Stable-diffusion\   DiT checkpoints (base, 2.9B, 3.8B bundle)          -> $AnimaDitDir
#   <root>\text_encoder\       qwen_3_06b_base.safetensors, qwen35_4b.safetensors  -> $AnimaTextEncoderDir
#   <root>\VAE\                qwen_image_vae.safetensors                          -> $AnimaVaeDir
#   <root>\qwen35_tokenizer\   tokenizer.json + tokenizer_config.json (3.8B only)  -> $AnimaQwen35TokenizerDir
# Relative paths are resolved from the folder you run the launcher in.

# Full file-system path: relative paths are resolved from the current folder, ".." is collapsed, and UNC or
# provider-qualified paths come back in a form Python can open. Nothing is globbed, so [ ] in names are fine.
function ConvertTo-AnimaFullPath([string]$Path) {
    try { return $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($Path) }
    catch { return $Path }  # e.g. a drive letter that does not exist: keep it; the file check reports it missing
}

$AnimaRepoRoot = ConvertTo-AnimaFullPath (Join-Path $PSScriptRoot "..\..")

$AnimaModelRoot = Join-Path $AnimaRepoRoot "models"
if ($env:ANIMA_MODEL_ROOT) { $AnimaModelRoot = $env:ANIMA_MODEL_ROOT }

# Folders; left empty here they default to the <root> subfolders above (models.local.ps1 may set them)
$AnimaDitDir = $null
$AnimaTextEncoderDir = $null
$AnimaVaeDir = $null
$AnimaQwen35TokenizerDir = $null
if ($env:ANIMA38_QWEN35_TOKENIZER_DIR) { $AnimaQwen35TokenizerDir = $env:ANIMA38_QWEN35_TOKENIZER_DIR }

# DiT checkpoints (in $AnimaDitDir)
$AnimaBaseFile = "anima-base-v1.0.safetensors"        # Anima base 1.0 (train_anima_base.ps1, train_anima_fft.ps1)
$Anima29File = "Anima-2.9B-preview-v1.safetensors"    # Anima-2.9B preview (train_anima29.ps1)
$Anima38File = "Anima-3.8B-v1.1.safetensors"          # Anima-3.8B v1.1 bundle with the connector (train_anima38.ps1)

# Text encoders (in $AnimaTextEncoderDir) and VAE (in $AnimaVaeDir)
$AnimaQwen3File = "qwen_3_06b_base.safetensors"       # Qwen3-0.6B, every Anima model
$AnimaQwen35File = "qwen35_4b.safetensors"            # Qwen3.5-4B, Anima-3.8B only
$AnimaVaeFile = "qwen_image_vae.safetensors"          # Qwen-Image VAE, every Anima model

# Optional per-user overrides (git-ignored), read last
$AnimaLocalModels = Join-Path $PSScriptRoot "models.local.ps1"
$AnimaLocalModelsError = $null  # reported (and the run refused) by the launcher
if (Test-Path -LiteralPath $AnimaLocalModels -PathType Leaf) {
    # read as UTF-8 with or without BOM (Windows PowerShell 5.1 reads a BOM-less .ps1 in the ANSI code page)
    try { . ([scriptblock]::Create([System.IO.File]::ReadAllText($AnimaLocalModels, [System.Text.Encoding]::UTF8))) }
    catch { $AnimaLocalModelsError = $_.ToString() }
}

$AnimaModelRoot = ConvertTo-AnimaFullPath $AnimaModelRoot
if (-not $AnimaDitDir) { $AnimaDitDir = [System.IO.Path]::Combine($AnimaModelRoot, "Stable-diffusion") }
if (-not $AnimaTextEncoderDir) { $AnimaTextEncoderDir = [System.IO.Path]::Combine($AnimaModelRoot, "text_encoder") }
if (-not $AnimaVaeDir) { $AnimaVaeDir = [System.IO.Path]::Combine($AnimaModelRoot, "VAE") }
if (-not $AnimaQwen35TokenizerDir) { $AnimaQwen35TokenizerDir = [System.IO.Path]::Combine($AnimaModelRoot, "qwen35_tokenizer") }
$AnimaDitDir = ConvertTo-AnimaFullPath $AnimaDitDir
$AnimaTextEncoderDir = ConvertTo-AnimaFullPath $AnimaTextEncoderDir
$AnimaVaeDir = ConvertTo-AnimaFullPath $AnimaVaeDir
$AnimaQwen35TokenizerDir = ConvertTo-AnimaFullPath $AnimaQwen35TokenizerDir
